def shortest_path(graph, source, target):
    heap = [(0, source, [])]
    discovered = {source: (0, [])}
    while heap:
        cost, node, path = heappop(heap)
        if node == target:
            return (cost, path + [target])
        for next_node, weight in graph.get(node, []):
