    def rsibs_shortest_path(graph, source, target, visited=None):
        if visited is None:
            visited = set()
        if source == target:
            return 0, [source]
        if source not in graph:
            return float("inf"), None
        min_distance = float("inf")
        min_path = None
        for neighbor, weight in graph[source]:
