                new_distance, new_path = rsibs_shortest_path(graph, neighbor, target, visited | {neighbor})
                if new_distance != float("inf"):
                    if new_distance + weight < min_distance:
                        min_distance = new_distance + weight
                        min_path = new_path + [neighbor]
        return min_distance, min_path

    # Perform the BFS to find the shortest path
    bfs_distance, bfs_path = bfs_shortest_path(graph, source, target)
    if bfs_distance != float("inf"):
