def shortest_path(graph, source, target):
    from collections import OrderedDict, deque
    from itertools import tee
    from heapq import heappop, heappush
    from math import inf

    def reached_target(node):
        return node == target

    def find_min_edge(node, edges_to):
        min_edge = (inf, None)
        for neighbor, weight in edges_to[node]:
            if weight < min_edge[0]:
                min_edge = (weight, neighbor)
        return min_edge
    priority_queue = [(0, source, [])]
    visited = set()
    distance = {}
    path = {}
    distance[source] = 0
    path[source] = []
    for node in graph:
        if node != source:
            distance[node] = inf
            path[node] = None
    while priority_queue:
        current_distance, current_node, current_path = heappop(priority_queue)
        if current_node in visited:
            continue
        visited.add(current_node)
        if reached_target(current_node):
            return (current_distance, current_path)
        next_node, next_edge = find_min_edge(current_node, graph)
        new_distance = current_distance + next_edge
        if new_distance < distance[next_node]:
            distance[next_node] = new_distance
            path[next_node] = current_path + [current_node]
            heappush(priority_queue, (new_distance, next_node, current_path + [current_node]))
    return (inf, None)
