import heapq

def shortest_path(graph, source, target):

    def neighbors(node):
        return [(n, w) for n, w in graph[node] if n is not None]

    def dijkstra(edges, start, end):
        inf = float('inf')
        G = {}
        for v in edges:
            G[v] = {n: inf if w is None else w for n, w in edges[v]}
        Q = [(0, start, [start])]
        seen = set()
        while Q:
            cost, v1, path = heapq.heappop(Q)
            if v1 not in seen:
                seen.add(v1)
                if v1 == end:
                    return (path, cost)
                for v2, weight in neighbors(v1):
                    if v2 not in seen:
                        heapq.heappush(Q, (cost + weight, v2, path + [v2]))
        return (None, inf)
    path, cost = dijkstra(graph, source, target)
    if path is None:
        return (float('inf'), None)
    else:
        return (cost, path)

from collections import deque

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)
    reachable = set()
    queue = deque([source])
    reachable.add(source)
    while queue:
        current = queue.popleft()
        for neighbor, _ in graph[current]:
            if neighbor not in reachable:
                queue.append(neighbor)
                reachable.add(neighbor)
    if target not in reachable:
        return (float('inf'), None)

    def shortest_path_rec(graph, source, target, distance=0, path=None):
        if path is None:
            path = [source]
        if source == target:
            return (distance, path)
        min_distance, min_path = (float('inf'), None)
        for neighbor, weight in graph[source]:
            if neighbor not in path:
                new_distance = distance + weight
                new_path = path + [neighbor]
                distance, path = shortest_path_rec(graph, neighbor, target, new_distance, new_path)
                if distance < min_distance:
                    min_distance, min_path = (distance, path)
        return (min_distance, min_path)
    distance, path = shortest_path_rec(graph, source, target)
    return (distance, path)
